'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let token='',canWrite=false,connected=false,selectedJob=null,jobs=[],datasets=[],gpus=[],polling=false,submitting=false,latestDetail=null,pendingSubmission=null;
const statusNames={queued:'排队中',running:'训练中',cancelling:'正在停止',cancelled:'已取消',failed:'失败',succeeded:'已完成',interrupted:'已中断'};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000)}
async function api(path,options={}){const response=await fetch('/api'+path,{...options,headers:{Authorization:'Bearer '+token,...options.headers}});let result;try{result=await response.json()}catch{throw new Error('服务返回了非 JSON 内容，请确认通过自部署地址访问')}if(!response.ok){if(response.status===401){connected=false;token='';$('#console').hidden=true;$('#login').hidden=false;$('#connection').textContent='认证已失效'}const e=result.detail;throw new Error(Array.isArray(e)?e.map(x=>x.msg).join('；'):e||'请求失败')}return result}
async function check(){try{const r=await fetch('/api/health');const health=await r.json();if(!r.ok||health.service!=='trainlab-pretraining')throw new Error();$('#notice').textContent='训练服务已启动。连接后可查看 GPU、上传语料并提交预训练任务。';$('#login').hidden=false;$('#connection').textContent='等待连接'}catch{$('#notice').textContent='当前为在线界面预览。请在你的 Linux 机器上部署 TrainLab，再通过该机器的地址打开此页面。';$('#connection').textContent='未连接 GPU 机器';$('#offline').hidden=false}}
$('#login').onsubmit=async e=>{e.preventDefault();token=$('#token').value.trim();try{const system=await api('/system');connected=true;$('#token').value='';$('#login').hidden=true;$('#console').hidden=false;$('#notice').textContent='从随机权重预训练 · 模型、分词器和数据保留在这台服务器 · 同时只运行一个任务';$('#connection').textContent='已连接训练服务';paintSystem(system,true);await refresh();budget()}catch(err){token='';toast(err.message)}};
function paintSystem(s,initial=false){gpus=s.gpus;canWrite=s.identity?.role!=='viewer';$('#connection').textContent=s.identity?`${s.identity.subject} · ${s.identity.project} · ${s.identity.role}`:'已连接';$('#upload').disabled=!canWrite;$('#submit-job').disabled=!canWrite;$('#notice').textContent=`个人凭据认证 · ${s.scheduler_alive?'调度器运行中':'调度器未就绪'} · 单机串行 DDP · API 项目权限隔离`;$('#gpu-description').textContent=`${gpus.length} 张 GPU · 单任务队列`;$('#gpu-cards').innerHTML=gpus.length?gpus.map(g=>`<div class="gpu-card"><strong>GPU ${g.index}</strong><p title="${esc(g.name)}">${esc(g.name)}</p><div class="vram">${(g.memory_used_mib/1024).toFixed(1)} <small>/ ${(g.memory_total_mib/1024).toFixed(1)} GiB</small></div><div class="progress-track"><div style="width:${Math.min(100,g.memory_used_mib/g.memory_total_mib*100)}%"></div></div><p>利用率 ${g.utilization_percent}% · 驱动 ${esc(g.driver)}</p></div>`).join(''):`<div class="callout">${esc(s.error||'没有可用 GPU')}</div>`;if(initial){$('#gpu-select').innerHTML=gpus.map((g,i)=>`<label><input type="checkbox" name="gpu" value="${g.index}" ${i===0?'checked':''}>GPU ${g.index}</label>`).join('');$('#gpu-select').querySelectorAll('input').forEach(x=>x.onchange=budget)}}
function config(){const sizes={tiny:[6,384,6],small:[12,768,12],medium:[24,1024,16]},[layers,hidden_size,heads]=sizes[$('#preset').value];return{name:$('#job-name').value,dataset_id:$('#dataset').value,gpu_ids:[...document.querySelectorAll('[name=gpu]:checked')].map(x=>+x.value),layers,hidden_size,heads,seq_length:+$('#seq').value,vocab_size:+$('#vocab').value,micro_batch:+$('#micro').value,grad_accum:+$('#accum').value,max_steps:+$('#steps').value,learning_rate:+$('#learning-rate').value,warmup_ratio:.03,weight_decay:.1,eval_steps:+$('#interval').value,save_steps:+$('#interval').value,seed:42,precision:$('#precision').value,gradient_checkpointing:true,max_runtime_seconds:+$('#runtime').value*60}}
function budget(){const c=config(),h=c.hidden_size,p=c.vocab_size*h+c.seq_length*h+c.layers*(12*h*h+13*h)+2*h,b=c.micro_batch*c.grad_accum*c.gpu_ids.length;$('#budget').innerHTML=`约 <b>${(p/1e6).toFixed(1)}M</b> 参数 · 有效 batch <b>${b}</b><br>每步约 ${(b*c.seq_length).toLocaleString()} tokens<br>计划处理 ${(b*c.seq_length*c.max_steps/1e6).toFixed(2)}M tokens（含重复遍历）<br><small>参数量按词表上限估计，不代表显存保证。</small>`}
$('#job-form').addEventListener('input',budget);$('#job-form').addEventListener('change',budget);
function paintDatasets(){const old=$('#dataset').value;$('#dataset').innerHTML='<option value="">请选择已上传语料</option>'+datasets.map(d=>`<option value="${esc(d.id)}">${esc(d.name)} · ${d.rows} 篇</option>`).join('');if(datasets.some(d=>d.id===old))$('#dataset').value=old;else if(datasets.length)$('#dataset').value=datasets[0].id}
$('#upload').onclick=async()=>{const file=$('#corpus-file').files[0];if(!file)return toast('先选择一个 JSONL 文件');if(file.size>100*1024*1024)return toast('语料最多为 100 MiB');$('#upload').disabled=true;$('#upload-state').textContent='正在上传并检查数据格式…';try{const d=await api('/datasets?name='+encodeURIComponent(file.name),{method:'POST',body:file,headers:{'Content-Type':'application/octet-stream'}});datasets=await api('/datasets');paintDatasets();$('#dataset').value=d.id;$('#upload-state').textContent=`已保存 ${d.rows} 篇文档 · ${(d.bytes/1024/1024).toFixed(2)} MiB`;toast('语料已保存到服务器')}catch(e){$('#upload-state').textContent=e.message}finally{$('#upload').disabled=!canWrite}};
$('#job-form').onsubmit=async e=>{e.preventDefault();if(submitting)return;const c=config();if(!c.gpu_ids.length)return toast('至少选择一张 GPU');if(c.eval_steps>c.max_steps)return toast('评估与保存间隔不能超过总更新步数');const payload=JSON.stringify(c);if(!pendingSubmission||pendingSubmission.payload!==payload)pendingSubmission={payload,key:[...crypto.getRandomValues(new Uint8Array(16))].map(x=>x.toString(16).padStart(2,'0')).join('')};submitting=true;$('#submit-job').disabled=true;try{const j=await api('/jobs',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':pendingSubmission.key},body:payload});selectedJob=j.id;pendingSubmission=null;toast('预训练任务已提交');await refresh()}catch(err){toast(err.message)}finally{submitting=false;$('#submit-job').disabled=!canWrite}};
function paintJobs(){ $('#job-count').textContent=`${jobs.length} 个任务`;$('#jobs').className=jobs.length?'jobs-list':'jobs-list empty';$('#jobs').innerHTML=jobs.length?jobs.map(j=>`<button class="job-row ${selectedJob===j.id?'selected':''}" data-job="${j.id}"><div><strong>${esc(j.config.name)}</strong><small>${j.config.layers} 层 · ${j.config.hidden_size} 维 · ${j.config.gpu_ids.length} 卡 · ${new Date(j.created_at).toLocaleString('zh-CN')}</small></div><span class="badge ${j.status==='succeeded'||j.status==='running'?'green':'gray'}">${statusNames[j.status]||esc(j.status)}</span></button>`).join(''):'尚无训练任务';document.querySelectorAll('[data-job]').forEach(b=>b.onclick=async()=>{selectedJob=b.dataset.job;paintJobs();try{await detail()}catch(e){toast(e.message)}})}
async function refresh(){if(!connected||polling)return;polling=true;try{const [s,ds,js]=await Promise.all([api('/system'),api('/datasets'),api('/jobs')]);paintSystem(s);datasets=ds;paintDatasets();jobs=js;if(!selectedJob&&jobs.length)selectedJob=jobs[0].id;paintJobs();await detail()}catch(e){toast(e.message)}finally{polling=false}}
async function detail(){if(!selectedJob)return;const jid=selectedJob;const [j,l]=await Promise.all([api('/jobs/'+jid),api('/jobs/'+jid+'/logs')]);if(jid!==selectedJob)return;latestDetail=j;$('#detail-title').textContent=j.config.name;$('#job-status').textContent=statusNames[j.status]||j.status;const m=j.metrics||[],loss=[...m].reverse().find(x=>x.loss!==undefined),val=[...m].reverse().find(x=>x.eval_loss!==undefined),step=m.length?m[m.length-1].step:0;const oldLog=$('#job-log'),scroll=oldLog?oldLog.scrollTop:0,atBottom=!oldLog||oldLog.scrollHeight-oldLog.scrollTop-oldLog.clientHeight<30;$('#job-detail').innerHTML=`<div class="job-metrics"><div><small>训练 Loss</small><b>${loss?Number(loss.loss).toFixed(4):'—'}</b></div><div><small>验证 Loss</small><b>${val?Number(val.eval_loss).toFixed(4):'—'}</b></div><div><small>更新步数</small><b>${step} <small>/ ${j.config.max_steps}</small></b></div></div><div class="job-progress"><div class="progress-track"><div style="width:${Math.min(100,100*step/j.config.max_steps)}%"></div></div></div><p class="metric-label">紫色：训练 Loss · 绿色：验证 Loss · 空白表示尚无实测数据</p><div class="job-chart"><canvas id="server-chart" aria-label="服务端训练与验证损失曲线"></canvas></div>${j.error?`<div class="job-error">${esc(j.error)}</div>`:''}<div class="detail-actions">${canWrite&&['queued','running'].includes(j.status)?'<button class="button" id="cancel-job">停止此任务</button>':''}${canWrite&&['failed','cancelled','interrupted'].includes(j.status)&&j.checkpoints.length?'<button class="button primary" id="resume-job">从最新完整检查点恢复</button>':''}<span class="mini-note">${j.checkpoints.length} 个完整检查点 · ${j.config.gpu_ids.length} 卡 DDP</span></div><pre id="job-log" class="job-log">${esc(l.text||'任务准备中，等待训练进程输出…')}</pre>${j.summary?`<div class="text-body"><strong>验证 Perplexity：${j.summary.perplexity?j.summary.perplexity.toFixed(2):'未计算'}</strong><p class="mini-note">仅在同一分词器和验证集内比较。此训练未设置独立测试集。</p></div>`:''}${j.artifacts.length?`<div class="artifact-list"><strong>模型与训练产物</strong>${j.artifacts.filter(a=>!a.path.startsWith('prepared/')).map(a=>`<button data-artifact="${esc(a.path)}">↓ ${esc(a.path)} <span class="muted">${(a.bytes/1024/1024).toFixed(2)} MiB</span></button>`).join('')}</div>`:''}`;const log=$('#job-log');log.scrollTop=atBottom?log.scrollHeight:scroll;if($('#cancel-job'))$('#cancel-job').onclick=()=>mutate(jid,'cancel');if($('#resume-job'))$('#resume-job').onclick=()=>mutate(jid,'resume');document.querySelectorAll('[data-artifact]').forEach(b=>b.onclick=()=>{const item=j.artifacts.find(a=>a.path===b.dataset.artifact);if(item&&item.bytes>256*1024*1024){toast('文件大于 256 MiB，请在服务器 output 目录复制，或使用带鉴权的下载 API');return}artifact(jid,b.dataset.artifact)});drawChart(j)}
async function mutate(jid,action){try{const j=await api('/jobs/'+jid+'/'+action,{method:'POST'});selectedJob=j.id;await refresh();toast(action==='resume'?'恢复任务已入队':'停止请求已处理')}catch(e){toast(e.message)}}
async function artifact(jid,path){try{const r=await fetch('/api/jobs/'+jid+'/artifact/'+path.split('/').map(encodeURIComponent).join('/'),{headers:{Authorization:'Bearer '+token}});if(!r.ok)throw new Error('文件下载失败');const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=path.split('/').pop();a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}catch(e){toast(e.message)}}
function drawChart(j){const canvas=$('#server-chart');if(!canvas)return;const rect=canvas.getBoundingClientRect(),w=rect.width,h=rect.height,dpr=window.devicePixelRatio||1;canvas.width=w*dpr;canvas.height=h*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);const m=j.metrics||[],values=m.flatMap(x=>[x.loss,x.eval_loss]).filter(Number.isFinite),max=Math.max(1,...values)*1.1;const left=35,top=15,pw=w-48,ph=h-42;c.font='12px sans-serif';c.fillStyle='#98a0ab';for(let i=0;i<5;i++){const y=top+ph*i/4;c.strokeStyle='#eceff4';c.beginPath();c.moveTo(left,y);c.lineTo(w,y);c.stroke();c.fillText((max*(1-i/4)).toFixed(1),0,y+4);c.fillText(Math.round(j.config.max_steps*i/4),left+pw*i/4-8,h-3)}for(const [key,color]of[['loss','#8b74d9'],['eval_loss','#60b699']]){const points=m.filter(x=>Number.isFinite(x[key]));c.beginPath();c.strokeStyle=color;c.lineWidth=2;points.forEach((x,i)=>{const px=left+pw*x.step/j.config.max_steps,py=top+ph*(1-x[key]/max);i?c.lineTo(px,py):c.moveTo(px,py)});c.stroke();for(const x of points){c.fillStyle=color;c.beginPath();c.arc(left+pw*x.step/j.config.max_steps,top+ph*(1-x[key]/max),2,0,Math.PI*2);c.fill()}}}
$('#refresh').onclick=refresh;setInterval(()=>{if(!document.hidden)refresh()},4000);window.addEventListener('resize',()=>{if(latestDetail)drawChart(latestDetail)});check();
